fered":{"@type":"Service","name":"Hurricane & Nor’easter Appraisal","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/hurricane-noreaster-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Appraisal","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/burst-pipe-water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow Load & Ice Dam Appraisal","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/snow-load-ice-dam-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://newyorkinsuranceappraiser.com/claim-appraisals/appraisal-umpire-services/"}}]},"description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims across New York State.","areaServed":[{"@type":"State","name":"New York"},{"@type":"City","name":"Manhattan"},{"@type":"City","name":"Brooklyn"},{"@type":"City","name":"Queens"},{"@type":"City","name":"Staten Island"},{"@type":"City","name":"Hempstead"},{"@type":"City","name":"Islip"},{"@type":"City","name":"White Plains"},{"@type":"City","name":"Albany"},{"@type":"City","name":"Syracuse"},{"@type":"City","name":"Rochester"},{"@type":"City","name":"Buffalo"},{"@type":"City","name":"Binghamton"}],"priceRange":"$$","knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Xactimate estimating","Ice dam claims","Hurricane deductibles","Co-op and condo claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://newyorkinsuranceappraiser.com/#website","url":"https://newyorkinsuranceappraiser.com/","name":"New York Insurance Appraiser","publisher":{"@id":"https://newyorkinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#webpage","url":"https://newyorkinsuranceappraiser.com/claim-vocabulary/","name":"Insurance Claim Vocabulary | ACV, Umpire, Ice Dam & More","description":"Searchable plain-English definitions of property claim terms: actual cash value, appraisal award, hurricane deductible, ice dam, umpire and more.","inLanguage":"en-US","isPartOf":{"@id":"https://newyorkinsuranceappraiser.com/#website"},"about":{"@id":"https://newyorkinsuranceappraiser.com/#business"},"publisher":{"@id":"https://newyorkinsuranceappraiser.com/#business"},"dateModified":"2026-11-12","primaryImageOfPage":{"@type":"ImageObject","url":"https://newyorkinsuranceappraiser.com/assets/img/photos/laptop.webp","width":960,"height":640},"breadcrumb":{"@id":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#breadcrumb"},"mainEntity":{"@id":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://newyorkinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim vocabulary","item":"https://newyorkinsuranceappraiser.com/claim-vocabulary/"}],"@id":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claim vocabulary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"The value of damaged property after depreciation, usually replacement cost minus wear, age and obsolescence. Many policies pay ACV first and the rest after repairs.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Additional living expenses (ALE)","description":"Coverage for the increase in living costs, such as temporary housing, while your home is unlivable after a covered loss. It usually sits under Coverage D, loss of use.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss. It is the question an appraisal panel is generally limited to deciding.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by at least two of the three panel members that sets the amount of loss.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision that lets either party demand appraisal when they disagree on the amount of loss. Most versions descend from the New York Standard Fire Policy.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Coinsurance","description":"A clause, common in commercial policies, that reduces a payment if the property was insured for less than a set percentage of its value.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Competent and disinterested","description":"The standard an appraiser or umpire must meet under the New York form: qualified to value the loss and without a stake in the outcome.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage A (dwelling)","description":"The part of a homeowners policy that covers the house itself and attached structures.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage B (other structures)","description":"Coverage for detached structures on the property, such as a garage, shed or fence.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage C (personal property)","description":"Coverage for belongings such as furniture, clothing and electronics, often subject to special limits for certain items.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage D (loss of use)","description":"Coverage for additional living expenses or lost rental income while the home cannot be lived in after a covered loss.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing the insured, the property, coverage limits, deductibles and endorsements.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age, wear and condition that separates replacement cost from actual cash value.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Dwelling","description":"The main residence insured under a policy. Its limit often drives percentage deductibles.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Endorsement","description":"A written change to a policy that adds, removes or modifies coverage.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Hurricane deductible","description":"A deductible, often 1% to 5% of dwelling coverage, that applies only to losses from the hurricane or windstorm event the policy defines. Common on Long Island, in NYC and in coastal Westchester.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the roof edge that traps meltwater, which can then back up under shingles and leak into the home.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Ingress of water","description":"Water entering a building, a phrase often used in policies to distinguish how and where water got in, such as through a roof opening or from the ground.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate describing one task or material, with a quantity and unit price.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Loss assessment coverage","description":"Coverage that helps pay your share of a special assessment a co-op or condo board levies after a covered loss to common property.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Master policy","description":"The insurance policy a co-op corporation or condo association buys for the building and common areas.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs match in color, texture or style. Treatment varies by policy.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps taken after a loss to prevent further damage, such as tarping a roof or extracting water. Most policies require it.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"NFIP","description":"The National Flood Insurance Program, the federal program that writes most flood policies. Its policy has its own appraisal provision limited to certain disputes about value.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"NYPIUA (New York FAIR Plan)","description":"The New York Property Insurance Underwriting Association, the state’s residual market insurer for property owners who cannot find regular coverage.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Ordinance or law","description":"Coverage for added costs of repairing to current building codes, such as upgraded electrical or required demolition.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Overhead and profit (O&amp;P)","description":"The general contractor’s charge for managing a job and earning a margin, often expressed as a percentage added to an estimate when several trades are involved.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed that some policies require within a set time after the insurer requests it.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Public adjuster","description":"A professional licensed by the New York State Department of Financial Services to represent policyholders in presenting and negotiating claims, usually for a percentage fee.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation withheld from an ACV payment that the policy allows you to recover once repairs or replacement are completed.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Regulation 64","description":"The New York DFS regulation (11 NYCRR 216) that sets standards for how insurers handle and settle claims.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deducting depreciation.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which an insurer continues handling a claim while reserving the right to deny coverage later.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Scope of loss","description":"The description of what was damaged and what work is needed to repair it, separate from pricing.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Sewer backup endorsement","description":"An optional endorsement that adds coverage for water backing up through sewers or drains, often with its own limit.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Snow load","description":"The weight of accumulated snow and ice on a roof. Heavy lake-effect snow in Western and Central New York can stress or collapse roofs.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Square (roofing)","description":"A unit of roofing area equal to 100 square feet.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Subrogation","description":"The insurer’s right, after paying a claim, to recover from a third party who caused the loss.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Suit limitation","description":"A policy clause limiting how long you have to sue the insurer. Many New York property policies use two years from the loss; check yours.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an estimate after the initial inspection, often once hidden damage is found.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers cannot agree on.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Unit-owners (HO-6) policy","description":"A policy for a condo or co-op owner covering the interior of the unit, improvements, personal property and liability.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors that prices line items using regional cost data.","inDefinedTermSet":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"}],"@id":"https://newyorkinsuranceappraiser.com/claim-vocabulary/#definedtermset"}]}</script>
</head>
